using ImmichReverseGeo.Core.WorkerProtocol;

namespace ImmichReverseGeo.Tests;

[TestClass]
public class WorkerProtocolSerializationTests
{
    [TestMethod]
    public void Serialize_LifecycleAndProgressEvents_UseHandAuthoredUtf8()
    {
        AssertSerialized(WorkerProtocolV1TestData.Ready(), "{\"protocol\":\"immich-reversegeo.worker\",\"version\":1,\"direction\":\"worker-to-controller\",\"category\":\"lifecycle\",\"type\":\"ready\",\"sequence\":1,\"timestampUtc\":\"2026-08-29T12:00:00.0000000Z\",\"runId\":null,\"payload\":{}}"u8);
        AssertSerialized(new(WorkerProtocolV1.LifecycleCategory, WorkerProtocolV1.RunStartedType, 2, WorkerProtocolV1TestData.Start, WorkerProtocolV1TestData.RunId, new RunStartedPayload("manual", WorkerProtocolV1TestData.Start)), "{\"protocol\":\"immich-reversegeo.worker\",\"version\":1,\"direction\":\"worker-to-controller\",\"category\":\"lifecycle\",\"type\":\"run-started\",\"sequence\":2,\"timestampUtc\":\"2026-08-29T12:00:00.0000000Z\",\"runId\":\"01234567-89ab-cdef-0123-456789abcdef\",\"payload\":{\"trigger\":\"manual\",\"startedAtUtc\":\"2026-08-29T12:00:00.0000000Z\"}}"u8);
        AssertSerialized(new(WorkerProtocolV1.LifecycleCategory, WorkerProtocolV1.RunStartedType, 3, WorkerProtocolV1TestData.Start, WorkerProtocolV1TestData.RunId, new RunStartedPayload("scheduled", WorkerProtocolV1TestData.Start)), "{\"protocol\":\"immich-reversegeo.worker\",\"version\":1,\"direction\":\"worker-to-controller\",\"category\":\"lifecycle\",\"type\":\"run-started\",\"sequence\":3,\"timestampUtc\":\"2026-08-29T12:00:00.0000000Z\",\"runId\":\"01234567-89ab-cdef-0123-456789abcdef\",\"payload\":{\"trigger\":\"scheduled\",\"startedAtUtc\":\"2026-08-29T12:00:00.0000000Z\"}}"u8);
        AssertSerialized(new(WorkerProtocolV1.LifecycleCategory, WorkerProtocolV1.RunStartedType, 4, WorkerProtocolV1TestData.Start, WorkerProtocolV1TestData.RunId, new RunStartedPayload("run-once", WorkerProtocolV1TestData.Start)), "{\"protocol\":\"immich-reversegeo.worker\",\"version\":1,\"direction\":\"worker-to-controller\",\"category\":\"lifecycle\",\"type\":\"run-started\",\"sequence\":4,\"timestampUtc\":\"2026-08-29T12:00:00.0000000Z\",\"runId\":\"01234567-89ab-cdef-0123-456789abcdef\",\"payload\":{\"trigger\":\"run-once\",\"startedAtUtc\":\"2026-08-29T12:00:00.0000000Z\"}}"u8);
        AssertSerialized(new(WorkerProtocolV1.LifecycleCategory, WorkerProtocolV1.EligibilityDeterminedType, 5, WorkerProtocolV1TestData.Midpoint, WorkerProtocolV1TestData.RunId, new EligibilityDeterminedPayload(long.MaxValue)), "{\"protocol\":\"immich-reversegeo.worker\",\"version\":1,\"direction\":\"worker-to-controller\",\"category\":\"lifecycle\",\"type\":\"eligibility-determined\",\"sequence\":5,\"timestampUtc\":\"2026-08-29T12:00:01.0000000Z\",\"runId\":\"01234567-89ab-cdef-0123-456789abcdef\",\"payload\":{\"eligibleCount\":9223372036854775807}}"u8);
        AssertSerialized(new(WorkerProtocolV1.ProgressCategory, WorkerProtocolV1.ProgressChangedType, 6, WorkerProtocolV1TestData.Midpoint, WorkerProtocolV1TestData.RunId, new ProgressChangedPayload(3, 1, 1, 1)), "{\"protocol\":\"immich-reversegeo.worker\",\"version\":1,\"direction\":\"worker-to-controller\",\"category\":\"progress\",\"type\":\"progress-changed\",\"sequence\":6,\"timestampUtc\":\"2026-08-29T12:00:01.0000000Z\",\"runId\":\"01234567-89ab-cdef-0123-456789abcdef\",\"payload\":{\"processedCount\":3,\"updatedCount\":1,\"skippedCount\":1,\"failedCount\":1}}"u8);
    }

    [TestMethod]
    public void Serialize_ActivityAndLogVariants_UseHandAuthoredUtf8()
    {
        AssertSerialized(new(WorkerProtocolV1.ActivityCategory, WorkerProtocolV1.ActivityStartedType, 7, WorkerProtocolV1TestData.Midpoint, WorkerProtocolV1TestData.RunId, new ActivityStartedPayload(WorkerProtocolV1TestData.ActivityId, "download")), "{\"protocol\":\"immich-reversegeo.worker\",\"version\":1,\"direction\":\"worker-to-controller\",\"category\":\"activity\",\"type\":\"activity-started\",\"sequence\":7,\"timestampUtc\":\"2026-08-29T12:00:01.0000000Z\",\"runId\":\"01234567-89ab-cdef-0123-456789abcdef\",\"payload\":{\"activityId\":\"fedcba98-7654-3210-fedc-ba9876543210\",\"label\":\"download\"}}"u8);
        AssertSerialized(new(WorkerProtocolV1.ActivityCategory, WorkerProtocolV1.ActivityEndedType, 8, WorkerProtocolV1TestData.Midpoint, WorkerProtocolV1TestData.RunId, new ActivityEndedPayload(WorkerProtocolV1TestData.ActivityId)), "{\"protocol\":\"immich-reversegeo.worker\",\"version\":1,\"direction\":\"worker-to-controller\",\"category\":\"activity\",\"type\":\"activity-ended\",\"sequence\":8,\"timestampUtc\":\"2026-08-29T12:00:01.0000000Z\",\"runId\":\"01234567-89ab-cdef-0123-456789abcdef\",\"payload\":{\"activityId\":\"fedcba98-7654-3210-fedc-ba9876543210\"}}"u8);
        AssertSerialized(new(WorkerProtocolV1.DiagnosticCategory, WorkerProtocolV1.LogEmittedType, 9, WorkerProtocolV1TestData.Midpoint, WorkerProtocolV1TestData.RunId, new LogEmittedPayload("trace", "trace")), "{\"protocol\":\"immich-reversegeo.worker\",\"version\":1,\"direction\":\"worker-to-controller\",\"category\":\"diagnostic\",\"type\":\"log-emitted\",\"sequence\":9,\"timestampUtc\":\"2026-08-29T12:00:01.0000000Z\",\"runId\":\"01234567-89ab-cdef-0123-456789abcdef\",\"payload\":{\"level\":\"trace\",\"message\":\"trace\"}}"u8);
        AssertSerialized(new(WorkerProtocolV1.DiagnosticCategory, WorkerProtocolV1.LogEmittedType, 10, WorkerProtocolV1TestData.Midpoint, WorkerProtocolV1TestData.RunId, new LogEmittedPayload("information", "information")), "{\"protocol\":\"immich-reversegeo.worker\",\"version\":1,\"direction\":\"worker-to-controller\",\"category\":\"diagnostic\",\"type\":\"log-emitted\",\"sequence\":10,\"timestampUtc\":\"2026-08-29T12:00:01.0000000Z\",\"runId\":\"01234567-89ab-cdef-0123-456789abcdef\",\"payload\":{\"level\":\"information\",\"message\":\"information\"}}"u8);
        AssertSerialized(new(WorkerProtocolV1.DiagnosticCategory, WorkerProtocolV1.LogEmittedType, 11, WorkerProtocolV1TestData.Midpoint, WorkerProtocolV1TestData.RunId, new LogEmittedPayload("warning", "warning")), "{\"protocol\":\"immich-reversegeo.worker\",\"version\":1,\"direction\":\"worker-to-controller\",\"category\":\"diagnostic\",\"type\":\"log-emitted\",\"sequence\":11,\"timestampUtc\":\"2026-08-29T12:00:01.0000000Z\",\"runId\":\"01234567-89ab-cdef-0123-456789abcdef\",\"payload\":{\"level\":\"warning\",\"message\":\"warning\"}}"u8);
        AssertSerialized(new(WorkerProtocolV1.DiagnosticCategory, WorkerProtocolV1.LogEmittedType, 12, WorkerProtocolV1TestData.Midpoint, WorkerProtocolV1TestData.RunId, new LogEmittedPayload("error", "error")), "{\"protocol\":\"immich-reversegeo.worker\",\"version\":1,\"direction\":\"worker-to-controller\",\"category\":\"diagnostic\",\"type\":\"log-emitted\",\"sequence\":12,\"timestampUtc\":\"2026-08-29T12:00:01.0000000Z\",\"runId\":\"01234567-89ab-cdef-0123-456789abcdef\",\"payload\":{\"level\":\"error\",\"message\":\"error\"}}"u8);
    }

    [TestMethod]
    public void Serialize_TerminalVariants_UseHandAuthoredUtf8()
    {
        AssertSerialized(new(WorkerProtocolV1.TerminalCategory, WorkerProtocolV1.CompletedType, 13, WorkerProtocolV1TestData.End, WorkerProtocolV1TestData.RunId, new CompletedPayload("manual", WorkerProtocolV1TestData.Start, WorkerProtocolV1TestData.End, 0, 0, 0, 0)), "{\"protocol\":\"immich-reversegeo.worker\",\"version\":1,\"direction\":\"worker-to-controller\",\"category\":\"terminal\",\"type\":\"completed\",\"sequence\":13,\"timestampUtc\":\"2026-08-29T12:00:05.0000000Z\",\"runId\":\"01234567-89ab-cdef-0123-456789abcdef\",\"payload\":{\"trigger\":\"manual\",\"startedAtUtc\":\"2026-08-29T12:00:00.0000000Z\",\"endedAtUtc\":\"2026-08-29T12:00:05.0000000Z\",\"processedCount\":0,\"updatedCount\":0,\"skippedCount\":0,\"failedCount\":0,\"failureMessage\":null}}"u8);
        AssertSerialized(new(WorkerProtocolV1.TerminalCategory, WorkerProtocolV1.CancelledType, 14, WorkerProtocolV1TestData.End, WorkerProtocolV1TestData.RunId, new CancelledPayload("scheduled", WorkerProtocolV1TestData.Start, WorkerProtocolV1TestData.End, 0, 0, 0, 0)), "{\"protocol\":\"immich-reversegeo.worker\",\"version\":1,\"direction\":\"worker-to-controller\",\"category\":\"terminal\",\"type\":\"cancelled\",\"sequence\":14,\"timestampUtc\":\"2026-08-29T12:00:05.0000000Z\",\"runId\":\"01234567-89ab-cdef-0123-456789abcdef\",\"payload\":{\"trigger\":\"scheduled\",\"startedAtUtc\":\"2026-08-29T12:00:00.0000000Z\",\"endedAtUtc\":\"2026-08-29T12:00:05.0000000Z\",\"processedCount\":0,\"updatedCount\":0,\"skippedCount\":0,\"failedCount\":0,\"failureMessage\":null}}"u8);
        AssertSerialized(new(WorkerProtocolV1.TerminalCategory, WorkerProtocolV1.FailedType, 15, WorkerProtocolV1TestData.End, WorkerProtocolV1TestData.RunId, new FailedPayload("run-once", WorkerProtocolV1TestData.Start, WorkerProtocolV1TestData.End, 3, 1, 1, 1, "safe failure")), "{\"protocol\":\"immich-reversegeo.worker\",\"version\":1,\"direction\":\"worker-to-controller\",\"category\":\"terminal\",\"type\":\"failed\",\"sequence\":15,\"timestampUtc\":\"2026-08-29T12:00:05.0000000Z\",\"runId\":\"01234567-89ab-cdef-0123-456789abcdef\",\"payload\":{\"trigger\":\"run-once\",\"startedAtUtc\":\"2026-08-29T12:00:00.0000000Z\",\"endedAtUtc\":\"2026-08-29T12:00:05.0000000Z\",\"processedCount\":3,\"updatedCount\":1,\"skippedCount\":1,\"failedCount\":1,\"failureMessage\":\"safe failure\"}}"u8);
    }

    private static void AssertSerialized(WorkerProtocolEvent @event, ReadOnlySpan<byte> expectedUtf8)
    {
        CollectionAssert.AreEqual(expectedUtf8.ToArray(), WorkerProtocolCodec.Serialize(@event));

        var parsed = WorkerProtocolCodec.Parse(expectedUtf8);
        Assert.IsTrue(parsed.IsSuccess, parsed.Failure?.Diagnostic);
        Assert.AreEqual(@event, parsed.Event);
    }
}
